package com.smartmanager.nativeapp;
import android.content.*;import android.graphics.pdf.PdfDocument;import android.os.*;import android.print.*;import java.io.*;import java.util.*;
/** Print Framework adapter; input cards are immutable snapshots and archives are untouched. */
public final class AndroidPrintService {private AndroidPrintService(){}public static void print(Context c,String title,ArrayList<String[]> cards,CardTemplate t){PrintManager pm=(PrintManager)c.getSystemService(Context.PRINT_SERVICE);pm.print(title,new Adapter(cards,t),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setMinMargins(PrintAttributes.Margins.NO_MARGINS).build());}private static final class Adapter extends PrintDocumentAdapter{private final ArrayList<String[]>cards;private final CardTemplate t;Adapter(ArrayList<String[]>c,CardTemplate x){cards=new ArrayList<>(c);t=x;}public void onLayout(PrintAttributes old,PrintAttributes next,CancellationSignal cs,LayoutResultCallback cb,Bundle extras){if(cs.isCanceled()){cb.onLayoutCancelled();return;}cb.onLayoutFinished(new PrintDocumentInfo.Builder("smart-manager.pdf").setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).setPageCount(t.pages(cards.size())).build(),true);}public void onWrite(PageRange[] pages,ParcelFileDescriptor fd,CancellationSignal cs,WriteResultCallback cb){PdfDocument d=new PdfDocument();try{int i=0,n=1;float w=(t.paperW-2*t.margin-(t.columns-1)*t.gap)/(float)t.columns,h=(t.paperH-2*t.margin-(t.rows-1)*t.gap)/(float)t.rows;while(i<cards.size()&&!cs.isCanceled()){PdfDocument.Page p=d.startPage(new PdfDocument.PageInfo.Builder(t.paperW,t.paperH,n++).create());for(int k=0;k<t.perPage()&&i<cards.size();k++,i++)PdfService.drawCard(p.getCanvas(),cards.get(i),t,null,t.margin+(k%t.columns)*(w+t.gap),t.margin+(k/t.columns)*(h+t.gap),w,h);d.finishPage(p);}if(cs.isCanceled())cb.onWriteCancelled();else{d.writeTo(new FileOutputStream(fd.getFileDescriptor()));cb.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}}catch(Exception e){cb.onWriteFailed(e.getMessage());}finally{d.close();try{fd.close();}catch(Exception ignored){}}}}
}
